const ctx = $('Clean PDF Text').first().json;
const raw = $json.content?.[0]?.text || $json.message?.content?.[0]?.text || $json.text || '{}';
let knowledge;
try { knowledge = JSON.parse(raw.trim().replace(/^```json|```$/g,'')); }
catch(e){ throw new Error('Structurer did not return JSON: ' + e.message); }
return [{ json: { ...ctx, chapter_knowledge: knowledge } }];

const ctx = $('Build Prompt').item.json;
const raw = $json.content?.[0]?.text || $json.message?.content?.[0]?.text || $json.text || '{}';
let parsed;
try { parsed = JSON.parse(raw.trim().replace(/^```json|```$/g,'')); }
catch(e){ throw new Error('Generator returned non-JSON: ' + e.message); }
const questions = Array.isArray(parsed.questions) ? parsed.questions : [];
if (!questions.length) throw new Error('Generator returned 0 questions');
return [{ json: { ...ctx, generated_questions: questions } }];

const ctx = $('Parse Generation').item.json;
const raw = $json.content?.[0]?.text || $json.message?.content?.[0]?.text || $json.text || '{}';
let verdict;
try { verdict = JSON.parse(raw.trim().replace(/^```json|```$/g,'')); }
catch(e){ throw new Error('Validator returned non-JSON: ' + e.message); }
const byId = new Map((verdict.results||[]).map(r => [r.question_id, r]));
const keep = ctx.generated_questions.filter(q => byId.get(q.question_id)?.valid === true);
const rejected = ctx.generated_questions
  .filter(q => byId.get(q.question_id)?.valid !== true)
  .map(q => ({ id: q.question_id, issues: byId.get(q.question_id)?.issues || ['unknown'] }));
return [{ json: { ...ctx, validated_questions: keep, rejected, validator_verdict: verdict } }];

const ctx = $json;
const existing = (ctx.existing_stems || []).map(s => s.toLowerCase().replace(/\s+/g,' ').trim());
const seen = new Set();
const norm = s => s.toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();
function trigrams(s){ const t=norm(s); const g=new Set(); for(let i=0;i<=t.length-3;i++) g.add(t.slice(i,i+3)); return g; }
function jaccard(a,b){ const A=trigrams(a), B=trigrams(b); if(!A.size||!B.size) return 0; let inter=0; for(const x of A) if(B.has(x)) inter++; return inter/(A.size+B.size-inter); }
const threshold = 0.85;
const unique = [];
const dropped = [];
for (const q of (ctx.validated_questions||[])) {
  const stem = q.question || q.passage || '';
  const nstem = norm(stem);
  if (seen.has(nstem)) { dropped.push({id:q.question_id, reason:'duplicate_in_batch'}); continue; }
  let dup = false;
  for (const e of existing) { if (jaccard(stem, e) >= threshold) { dup = true; break; } }
  if (dup) { dropped.push({id:q.question_id, reason:'duplicate_vs_bank'}); continue; }
  seen.add(nstem);
  unique.push(q);
}
return [{ json: { ...ctx, unique_questions: unique, dropped_duplicates: dropped } }];

const ctx = $json;
const remaining = ctx.number_of_questions - (ctx.unique_questions||[]).length;
const existing_stems = [...(ctx.existing_stems||[]), ...(ctx.unique_questions||[]).map(q=>q.question||q.passage||'')];
return [{ json: { ...ctx, number_of_questions: remaining, existing_stems, kept_questions: ctx.unique_questions } }];

const ctx = $json;
const all = [...(ctx.kept_questions||[]), ...(ctx.unique_questions||[])];
// Re-id sequentially to keep ids tidy.
const diff = ctx.difficulty_code;
const tcode = ctx.question_type === 'CASE_STUDY' ? 'CS' : ctx.question_type;
const seen = new Set();
const questions = [];
let i = 1;
for (const q of all) {
  const key = (q.question || q.passage || '').toLowerCase().replace(/\s+/g,' ').trim();
  if (seen.has(key)) continue; seen.add(key);
  q.question_id = `${ctx.chapter_code}_${tcode}_${diff}_${String(i).padStart(3,'0')}`;
  i++; questions.push(q);
}
const out = {
  board: ctx.board,
  class: ctx.class_name,
  chapter: ctx.chapter,
  source_type: ctx.source_type,
  question_type: ctx.question_type,
  difficulty: ctx.difficulty,
  language: ctx.language,
  include_visual_questions: ctx.include_visual_questions,
  generate_explanation: ctx.generate_explanation,
  question_count: questions.length,
  generated_at: new Date().toISOString(),
  batch_id: ctx.batch_id,
  questions
};
const fname = `${ctx.chapter.replace(/[^A-Za-z0-9]+/g,'_')}_${ctx.question_type}_${ctx.difficulty}_${ctx.batch_id}.json`;
return [{ json: { ...ctx, final_payload: out, file_name: fname } }];

// Resolves Board / Class / Chapter / Type / Difficulty folder ids under root 'Question Bank',
// creating any missing folders via the Google Drive API using the OAuth credential
// configured at workflow level via $vars.GOOGLE_DRIVE_OAUTH_TOKEN (refreshed by sub-workflow).
// In practice, prefer the 'Google Drive: Folder' sub-workflow node — this Code node is the fallback.
const ctx = $json;
const rootName = $vars.DRIVE_ROOT || 'Question Bank';
const path = [rootName, ctx.board, ctx.class_name, ctx.chapter, ctx.question_type, ctx.difficulty];

async function findOrCreate(name, parentId) {
  const q = encodeURIComponent(`name='${name.replace(/'/g, "\\'")}' and mimeType='application/vnd.google-apps.folder' and '${parentId}' in parents and trashed=false`);
  const list = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'GET', url: `https://www.googleapis.com/drive/v3/files?q=${q}&fields=files(id,name)`, json: true
  });
  if (list.files && list.files.length) return list.files[0].id;
  const created = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'POST', url: 'https://www.googleapis.com/drive/v3/files',
    body: { name, mimeType: 'application/vnd.google-apps.folder', parents: [parentId] }, json: true
  });
  return created.id;
}

let parent = 'root';
const trail = [];
for (const seg of path) {
  parent = await findOrCreate.call(this, seg, parent);
  trail.push({ name: seg, id: parent });
}
return [{ json: { ...ctx, drive_folder_trail: trail, target_folder_id: parent } }];

// Pulls up to N recent files from the target Drive folder, downloads them, extracts question stems.
const ctx = $('Attach Knowledge Object').first().json;
const lookback = parseInt($vars.DUP_LOOKBACK || '20', 10);
const files = ($input.all() || []).flatMap(i => i.json.files || []).slice(0, lookback);
const stems = [];
for (const f of files) {
  try {
    const data = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
      method: 'GET', url: `https://www.googleapis.com/drive/v3/files/${f.id}?alt=media`, json: true
    });
    for (const q of (data.questions || [])) {
      const s = q.question || q.passage; if (s) stems.push(s);
    }
  } catch (e) { /* ignore broken files */ }
}
return [{ json: { ...ctx, target_folder_id: $('Ensure Drive Folders').first().json.target_folder_id, existing_stems: stems } }];

const ctx = $json;
const buffer = Buffer.from(JSON.stringify(ctx.final_payload, null, 2), 'utf8');
return [{ json: ctx, binary: { data: { data: buffer.toString('base64'), mimeType: 'application/json', fileName: ctx.file_name } } }];

const ctx = $json;
return [{ json: {
  status: 'OK',
  batch_id: ctx.batch_id,
  prompt_key: ctx.prompt_key,
  chapter: ctx.chapter,
  saved_file: ctx.file_name,
  questions_saved: ctx.final_payload.question_count,
  rejected_by_validator: (ctx.rejected || []).length,
  dropped_duplicates: (ctx.dropped_duplicates || []).length,
  drive_folder_trail: ctx.drive_folder_trail,
  attempts: ctx.attempt
}}];
